/** Dense metadata for one JS node id. */
export type NodeIndexEntry = {
    /** The packed local id and node type. */
    readonly packed: number;
};

export const NodeIndexEntry = {
    /** Encode this value. */
    encode(writer: BinaryWriter, value: NodeIndexEntry): void {
        encodeNodeIndexEntry(writer, value);
    },

    /** Decode one NodeIndexEntry. */
    decode(reader: BinaryReader): NodeIndexEntry {
        return decodeNodeIndexEntry(reader);
    },

    /** Return this value as JSON. */
    toJson(value: NodeIndexEntry): Json {
        return toJsonNodeIndexEntry(value);
    },

    /** Return one NodeIndexEntry from one JSON value. */
    fromJson(value: Json): NodeIndexEntry {
        return fromJsonNodeIndexEntry(value);
    },
};

/** Encode one NodeIndexEntry. */
export function encodeNodeIndexEntry(writer: BinaryWriter, value: NodeIndexEntry): void {
    writer.writeUnsigned(value.packed);
}

/** Decode one NodeIndexEntry. */
export function decodeNodeIndexEntry(reader: BinaryReader): NodeIndexEntry {
    const packed = reader.readNumber();

    return {
        packed,
    };
}

/** Return one JSON value for one NodeIndexEntry. */
export function toJsonNodeIndexEntry(value: NodeIndexEntry): Json {
    return {
        packed: value.packed,
    };
}

/** Return one NodeIndexEntry from one JSON value. */
export function fromJsonNodeIndexEntry(value: Json): NodeIndexEntry {
    const object = jsonObject(value);

    return {
        packed: jsonInteger(jsonField(object, "packed")),
    };
}

/** One DIR node that produced a JS node. */
export type NodeOrigin = {
    /** The origin module. */
    readonly moduleId: ModuleId;
    /** The origin DIR node id. */
    readonly nodeId: number;
};

export const NodeOrigin = {
    /** Encode this value. */
    encode(writer: BinaryWriter, value: NodeOrigin): void {
        encodeNodeOrigin(writer, value);
    },

    /** Decode one NodeOrigin. */
    decode(reader: BinaryReader): NodeOrigin {
        return decodeNodeOrigin(reader);
    },

    /** Return this value as JSON. */
    toJson(value: NodeOrigin): Json {
        return toJsonNodeOrigin(value);
    },

    /** Return one NodeOrigin from one JSON value. */
    fromJson(value: Json): NodeOrigin {
        return fromJsonNodeOrigin(value);
    },
};

/** Encode one NodeOrigin. */
export function encodeNodeOrigin(writer: BinaryWriter, value: NodeOrigin): void {
    encodeModuleId(writer, value.moduleId);
    writer.writeUnsigned(value.nodeId);
}

/** Decode one NodeOrigin. */
export function decodeNodeOrigin(reader: BinaryReader): NodeOrigin {
    const moduleId = decodeModuleId(reader);
    const nodeId = reader.readNumber();

    return {
        moduleId,
        nodeId,
    };
}

/** Return one JSON value for one NodeOrigin. */
export function toJsonNodeOrigin(value: NodeOrigin): Json {
    return {
        moduleId: toJsonModuleId(value.moduleId),
        nodeId: value.nodeId,
    };
}

/** Return one NodeOrigin from one JSON value. */
export function fromJsonNodeOrigin(value: Json): NodeOrigin {
    const object = jsonObject(value);

    return {
        moduleId: fromJsonModuleId(jsonField(object, "moduleId")),
        nodeId: jsonInteger(jsonField(object, "nodeId")),
    };
}

/** One stable symbol identity in lowered script output. */
export type ScriptSymbolId =
    /** One symbol lowered directly from source DIR. */
    | {
          readonly kind: "source";
          readonly source: GlobalSymbolId;
      }
    /** One generated default binding for one non-code script module. */
    | {
          readonly kind: "moduleDefault";
          readonly module_default: ModuleId;
      }
;

export const ScriptSymbolId = {
    /** One symbol lowered directly from source DIR. */
    source(source: GlobalSymbolId): ScriptSymbolId {
        return { kind: "source", source };
    },

    /** One generated default binding for one non-code script module. */
    moduleDefault(module_default: ModuleId): ScriptSymbolId {
        return { kind: "moduleDefault", module_default };
    },

    /** Encode this value. */
    encode(writer: BinaryWriter, value: ScriptSymbolId): void {
        encodeScriptSymbolId(writer, value);
    },

    /** Decode one ScriptSymbolId. */
    decode(reader: BinaryReader): ScriptSymbolId {
        return decodeScriptSymbolId(reader);
    },

    /** Return this value as JSON. */
    toJson(value: ScriptSymbolId): Json {
        return toJsonScriptSymbolId(value);
    },

    /** Return one ScriptSymbolId from one JSON value. */
    fromJson(value: Json): ScriptSymbolId {
        return fromJsonScriptSymbolId(value);
    },
};

/** Encode one ScriptSymbolId. */
export function encodeScriptSymbolId(writer: BinaryWriter, value: ScriptSymbolId): void {
    switch (value.kind) {
        case "source":
            writer.writeUnsigned(0);
            encodeGlobalSymbolId(writer, value.source);
            return;
        case "moduleDefault":
            writer.writeUnsigned(1);
            encodeModuleId(writer, value.module_default);
            return;
    }

    throw new SerdeError("unknown enum variant");
}

/** Decode one ScriptSymbolId. */
export function decodeScriptSymbolId(reader: BinaryReader): ScriptSymbolId {
    const variant = reader.readNumber();

    switch (variant) {
        case 0: {
            const source = decodeGlobalSymbolId(reader);

            return { kind: "source", source };
        }
        case 1: {
            const module_default = decodeModuleId(reader);

            return { kind: "moduleDefault", module_default };
        }
    }

    throw new SerdeError(`unknown enum variant index: ${variant}`);
}

/** Return one JSON value for one ScriptSymbolId. */
export function toJsonScriptSymbolId(value: ScriptSymbolId): Json {
    switch (value.kind) {
        case "source":
            return {
                kind: "source",
                source: toJsonGlobalSymbolId(value.source),
            };
        case "moduleDefault":
            return {
                kind: "moduleDefault",
                module_default: toJsonModuleId(value.module_default),
            };
    }

    throw new SerdeError("unknown enum variant");
}

/** Return one ScriptSymbolId from one JSON value. */
export function fromJsonScriptSymbolId(value: Json): ScriptSymbolId {
    const object = jsonObject(value);
    const kind = jsonString(jsonField(object, "kind"));

    switch (kind) {
        case "source":
            return {
                kind,
                source: fromJsonGlobalSymbolId(jsonField(object, "source")),
            };
        case "moduleDefault":
            return {
                kind,
                module_default: fromJsonModuleId(jsonField(object, "module_default")),
            };
    }

    throw new SerdeError(`unknown enum variant: ${kind}`);
}
